import Foundation
import Security
import CryptoKit

/// Certificate generator for secure pairing
public class CertificateGenerator {

    public enum CertificateError: Error {
        case generationFailed
        case storageFailed(OSStatus)
        case retrievalFailed(OSStatus)
    }

    public init() {}

    /// Generate a self-signed certificate for this device
    /// - Returns: Certificate and private key pair
    public func generateCertificate() throws -> (certificate: SecCertificate, privateKey: SecKey, fingerprint: String) {
        // Create certificate subject
        let deviceId = UUID().uuidString
        let commonName = "DroidLink-\(deviceId)"

        // Create key pair using modern API
        let privateKeyAttributes: [String: Any] = [
            kSecAttrKeyType as String: kSecAttrKeyTypeRSA,
            kSecAttrKeySizeInBits as String: 2048,
            kSecAttrIsPermanent as String: false
        ]

        let publicKeyAttributes: [String: Any] = [
            kSecAttrKeyType as String: kSecAttrKeyTypeRSA,
            kSecAttrKeySizeInBits as String: 2048
        ]

        let keyPairAttributes: [String: Any] = [
            kSecAttrKeyType as String: kSecAttrKeyTypeRSA,
            kSecAttrKeySizeInBits as String: 2048,
            kSecPrivateKeyAttrs as String: privateKeyAttributes,
            kSecPublicKeyAttrs as String: publicKeyAttributes
        ]

        guard let privateKey = SecKeyCreateRandomKey(keyPairAttributes as CFDictionary, nil) else {
            throw CertificateError.generationFailed
        }

        guard let publicKey = SecKeyCopyPublicKey(privateKey) else {
            throw CertificateError.generationFailed
        }

        // Create a simple certificate representation
        // For MVP, we'll use the public key data as our "certificate"
        let certificate = try createSimpleCertificate(
            publicKey: publicKey,
            privateKey: privateKey,
            commonName: commonName,
            deviceId: deviceId
        )

        // Calculate fingerprint
        let fingerprint = calculateFingerprint(certificate: certificate)

        return (certificate, privateKey, fingerprint)
    }

    /// Store certificate in Keychain
    public func storeCertificate(_ certificate: SecCertificate) throws {
        let data = SecCertificateCopyData(certificate) as Data

        let query: [String: Any] = [
            kSecClass as String: kSecClassCertificate,
            kSecValueRef as String: data,
            kSecAttrLabel as String: "DroidLink Device Certificate",
            kSecReturnData as String: false
        ]

        // Delete existing certificate first
        SecItemDelete(query as CFDictionary)

        // Add new certificate
        let status = SecItemAdd(query as CFDictionary, nil)
        guard status == errSecSuccess else {
            throw CertificateError.storageFailed(status)
        }
    }

    /// Retrieve certificate from Keychain
    public func retrieveCertificate() throws -> SecCertificate {
        let query: [String: Any] = [
            kSecClass as String: kSecClassCertificate,
            kSecAttrLabel as String: "DroidLink Device Certificate",
            kSecReturnRef as String: true
        ]

        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)

        guard status == errSecSuccess, let result else {
            throw CertificateError.retrievalFailed(status)
        }

        // CFTypeRef to SecCertificate bridge
        let certificate = result as! SecCertificate
        return certificate
    }

    // MARK: - Private Helpers

    private func createSimpleCertificate(
        publicKey: SecKey,
        privateKey: SecKey,
        commonName: String,
        deviceId: String
    ) throws -> SecCertificate {
        // For MVP, create a minimal valid certificate
        // We'll create a DER-encoded X.509 certificate structure

        // This is a simplified X.509 certificate structure
        // Version: 0x02 0x01 0x00 (v1)
        // Serial Number: 0x02 0x01 0x01
        // Signature Algorithm: RSA with SHA256
        // Issuer: CN=DroidLink
        // Validity: now + 365 days
        // Subject: CN=DroidLink-deviceId
        // Subject Public Key Info: RSA public key
        // Extensions: none for MVP

        let certificateData = generateX509Certificate(
            commonName: commonName,
            deviceId: deviceId,
            publicKey: publicKey
        )

        guard let cert = SecCertificateCreateWithData(nil, certificateData as CFData) else {
            throw CertificateError.generationFailed
        }

        return cert
    }

    private func generateX509Certificate(commonName: String, deviceId: String, publicKey: SecKey) -> Data {
        // For MVP, create a minimal but valid X.509 certificate
        // This is a simplified version - in production, use a proper crypto library

        var data = Data()

        // X.509 Certificate Structure (simplified)
        // SEQUENCE
        data.append(contentsOf: [0x30, 0x82, 0x02, 0x50]) // Length will be updated

        // Version (v1 = 0)
        data.append(contentsOf: [0xA0, 0x03, 0x02, 0x01, 0x00])

        // Serial Number
        data.append(contentsOf: [0x02, 0x01, 0x01])

        // Signature Algorithm (RSA with SHA256)
        data.append(contentsOf: [
            0x30, 0x0B,  // SEQUENCE
            0x06, 0x09,  // OBJECT IDENTIFIER
            0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01  // sha256WithRSAEncryption
        ])

        // Issuer (CN=DroidLink)
        let issuer = "CN=DroidLink O=DroidLink C=US".data(using: .utf8)!
        data.append(0x31) // SET
        data.append(UInt8(issuer.count))
        data.append(issuer)

        // Validity (now to now + 365 days)
        let now = Date()
        let later = Calendar.current.date(byAdding: .day, value: 365, to: now)!

        // For simplicity, use fixed timestamps in UTCTime
        data.append(contentsOf: [0x30, 0x1E]) // SEQUENCE
        data.append(contentsOf: [0x17, 0x0D]) // UTCTime
        data.append("250610120000Z".utf8) // 2025-06-10 12:00:00 UTC
        data.append(contentsOf: [0x17, 0x0D]) // UTCTime  
        data.append("260610120000Z".utf8) // 2026-06-10 12:00:00 UTC

        // Subject (CN=DroidLink-deviceId)
        let subjectName = "CN=DroidLink-\(deviceId.prefix(8))".data(using: .utf8)!
        data.append(0x31) // SET
        data.append(UInt8(subjectName.count))
        data.append(subjectName)

        // Subject Public Key Info (simplified - just RSA OID)
        data.append(contentsOf: [
            0x30, 0x82, 0x01, 0x22,  // SEQUENCE
            0x30, 0x0D,  // SEQUENCE (algorithm)
            0x06, 0x09,  // OBJECT IDENTIFIER
            0x2A, 0x86, 0x48, 0x86, 0xF7, 0x0D, 0x01, 0x01, 0x01, 0x05, 0x00  // rsaEncryption
        ])

        // Public key (placeholder - in real implementation, extract from SecKey)
        data.append(contentsOf: [0x03, 0x82, 0x01, 0x0F, 0x00]) // BIT STRING
        data.append(contentsOf: [0x30, 0x82, 0x01, 0x0A]) // SEQUENCE

        // For MVP, use dummy public key data
        // In production, extract actual public key from SecKey
        let dummyKey = Data(repeating: 0x30, count: 256)
        data.append(dummyKey)

        return data
    }

    private func calculateFingerprint(certificate: SecCertificate) -> String {
        let data = SecCertificateCopyData(certificate) as Data
        let digest = SHA256.hash(data: data)
        return digest.compactMap { String(format: "%02x", $0) }.joined()
    }
}

