class ContentViewModel: ObservableObject {
    @Published var state: ConnectionState = .disconnected
    @Published var qrCode: NSImage? = nil
    @Published var errorMessage: String = ""

    private var certificateGenerator = CertificateGenerator()
    private var qrCodeGenerator = QRCodeGenerator()

    func startPairing() {
        print("🚀 Starting pairing process...")
        state = .pairing
        errorMessage = ""

        Task {
            do {
                print("📝 Generating certificate...")
                // Generate certificate
                let (certificate, _, fingerprint) = try certificateGenerator.generateCertificate()
                print("✅ Certificate generated!")

                print("💾 Storing certificate in Keychain...")
                // Store certificate
                try certificateGenerator.storeCertificate(certificate)
                print("✅ Certificate stored!")

                print("📱 Getting device info...")
                // Get device info
                let deviceId = getCurrentDeviceId()
                let deviceName = getCurrentDeviceName()
                print("✅ Device ID: \(deviceId.prefix(8))...")
                print("✅ Device Name: \(deviceName)")
                print("✅ Fingerprint: \(fingerprint.prefix(16))...")

                // Generate QR code
                await MainActor.run {
                    print("🖼️ Generating QR code...")
                    self.qrCode = self.qrCodeGenerator.generateQRCode(
                        deviceId: deviceId,
                        deviceName: deviceName,
                        certificateFingerprint: fingerprint
                    )

                    if self.qrCode != nil {
                        print("✅ QR code generated successfully!")
                    } else {
                        print("❌ QR code generation failed!")
                        self.errorMessage = "Failed to generate QR code"
                    }
                }

                // Wait for Android to scan (timeout after 5 minutes)
                print("⏳ Waiting for Android to scan QR code...")
                try await Task.sleep(nanoseconds: 300_000_000_000)

                // If no scan, cancel pairing
                await MainActor.run {
                    print("⏰ Timeout - no scan detected")
                    self.state = .disconnected
                    self.qrCode = nil
                }

            } catch {
                print("❌ Error: \(error)")
                await MainActor.run {
                    self.errorMessage = "Error: \(error.localizedDescription)"
                    self.state = .disconnected
                    self.qrCode = nil
                }
            }
        }
    }

    func cancelPairing() {
        print("❌ Pairing cancelled")
        state = .disconnected
        qrCode = nil
        errorMessage = ""
    }

    func disconnect() {
        // TODO: Implement disconnect
        print("🔌 Disconnecting")
        state = .disconnected
    }

    private func getCurrentDeviceId() -> String {
        var size: Int = 0
        sysctlbyname("hw.uuid", nil, &size, nil, 0)
        var uuid = [CChar](repeating: 0, count: size)
        sysctlbyname("hw.uuid", &uuid, &size, nil, 0)
        return String(decoding: uuid.prefix(while: { $0 != 0 }), as: UTF8.self)
    }

    private func getCurrentDeviceName() -> String {
        let host = ProcessInfo.processInfo.hostName
        return Host.current().localizedName ?? host
    }
}

