        var serialNumber: String?

        if let uuid = platformExpert.serialNumber {
            serialNumber = uuid
        } else {
            // Fallback to hardware UUID
            var size: Int = 0
            sysctlbyname("kern.uuid", nil, &size, nil, 0)
            if size > 0 {
                var uuidBytes = [UInt8](repeating: 0, count: size)
                sysctlbyname("kern.uuid", &uuidBytes, &size, nil, 0)
                let nullIndex = uuidBytes.firstIndex(of: 0) ?? uuidBytes.count
                serialNumber = String(decoding: uuidBytes[0..<nullIndex], as: UTF8.self)
            }
        }

        return serialNumber ?? UUID().uuidString
    }

