// Helper for platform UUID
import IOKit
private func IOPlatformExpertDevice() -> io_service_t {
    let masterPort = mach_host_self()
    let matching = IOServiceMatching("IOPlatformExpertDevice")
    var service: io_service_t = 0
    IOServiceGetMatchingService(masterPort, matching, &service)
    return service
}

extension io_service_t {
    var serialNumber: String? {
        var property: Unmanaged<CFString>?
        let result = IORegistryEntryCreateCFProperty(self, "IOPlatformSerialNumber" as CFString, kCFAllocatorDefault, 0)

        if case let .some(unmanaged) = result {
            property = unmanaged
            return property?.takeRetainedValue() as String? ?? nil
        }

        return nil
    }
}

