import Foundation
import Security
import CryptoKit

/// Certificate generator for secure pairing
public class CertificateGenerator {

    public enum CertificateError: Error {
        case generationFailed
        case storageFailed(OSStatus)
        case retrievalFailed(OSStatus)
    }

    public init() {}

    /// Generate a self-signed certificate for this device
    /// - Returns: Certificate and private key pair
    public func generateCertificate() throws -> (certificate: SecCertificate, privateKey: SecKey, fingerprint: String) {
        print("🔑 Generating key pair...")

        // Create key pair using modern API
        let privateKeyAttributes: [String: Any] = [
            kSecAttrKeyType as String: kSecAttrKeyTypeRSA,
            kSecAttrKeySizeInBits as String: 2048,
            kSecAttrIsPermanent as String: false
        ]

        guard let privateKey = SecKeyCreateRandomKey(privateKeyAttributes as CFDictionary, nil) else {
            print("❌ Failed to create private key")
            throw CertificateError.generationFailed
        }

        guard let publicKey = SecKeyCopyPublicKey(privateKey) else {
            print("❌ Failed to get public key")
            throw CertificateError.generationFailed
        }

        print("✅ Key pair created successfully")

        // Extract public key data for fingerprint
        guard let publicKeyData = try? SecKeyCopyExternalRepresentation(publicKey, nil) as Data? else {
            print("❌ Failed to extract public key data")
            throw CertificateError.generationFailed
        }

        // Calculate fingerprint from public key
        let fingerprint = SHA256.hash(data: publicKeyData)
        let fingerprintHex = fingerprint.compactMap { String(format: "%02x", $0) }.joined()

        print("✅ Fingerprint: \(fingerprintHex.prefix(16))...")

        // Create a dummy certificate for storage (MVP - use public key as "certificate")
        let certData = publicKeyData
        guard let certificate = SecCertificateCreateWithData(nil, certData as CFData) else {
            print("❌ Failed to create certificate from data")
            throw CertificateError.generationFailed
        }

        return (certificate, privateKey, fingerprintHex)
    }

    /// Store certificate in Keychain
    public func storeCertificate(_ certificate: SecCertificate) throws {
        let data = SecCertificateCopyData(certificate) as Data

        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: "DroidLinkCertificate",
            kSecAttrService as String: "DroidLink",
            kSecValueData as String: data,
            kSecReturnData as String: false
        ]

        // Delete existing first
        SecItemDelete(query as CFDictionary)

        // Add new
        let status = SecItemAdd(query as CFDictionary, nil)

        // Ignore duplicate item error
        if status != errSecSuccess && status != errSecDuplicateItem {
            print("❌ Failed to store certificate: \(status)")
            throw CertificateError.storageFailed(status)
        }

        print("✅ Certificate stored in Keychain")
    }

    /// Retrieve certificate from Keychain
    public func retrieveCertificate() throws -> SecCertificate {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: "DroidLinkCertificate",
            kSecAttrService as String: "DroidLink",
            kSecReturnData as String: true
        ]

        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)

        guard status == errSecSuccess, let result else {
            throw CertificateError.retrievalFailed(status)
        }

        let data = result as! Data
        guard let certificate = SecCertificateCreateWithData(nil, data as CFData) else {
            throw CertificateError.generationFailed
        }

        return certificate
    }
}

