    @Published var qrCode: NSImage? = nil
    @Published var errorMessage: String = ""

    private var certificateGenerator = CertificateGenerator()
    private var qrCodeGenerator = QRCodeGenerator()

    init() {
        print("🎨 ContentViewModel initialized")
    }

    func startPairing() {
        print("🚀 Starting pairing process...")
        state = .pairing
        errorMessage = ""
        qrCode = nil

        Task {
            do {
                print("📝 Step 1: Generating key pair and fingerprint...")
                let (_, _, fingerprint) = try certificateGenerator.generateCertificate()
                print("✅ Fingerprint: \(fingerprint.prefix(16))...")

                // Skip Keychain storage for MVP - use in-memory only
                print("💾 Step 2: Skipping Keychain storage (MVP mode)")

                print("📱 Step 3: Getting device info...")
                let deviceId = getCurrentDeviceId()
                let deviceName = getCurrentDeviceName()
                print("✅ Device ID: \(deviceId)")
                print("✅ Device Name: \(deviceName)")

                print("🖼️ Step 4: Generating QR code...")
                let qr = self.qrCodeGenerator.generateQRCode(
                    deviceId: deviceId,
                    deviceName: deviceName,
                    certificateFingerprint: fingerprint
                )

                await MainActor.run {
                    self.qrCode = qr
                    if qr != nil {
                        print("✅ QR code generated successfully!")
                        print("📐 QR size: \(qr!.size.width) x \(qr!.size.height)")
                    } else {
                        print("❌ QR code generation returned nil!")
                        self.errorMessage = "Failed to generate QR code"
                    }
                }

                print("⏳ Step 5: Waiting for Android scan (5 minutes)...")
                try await Task.sleep(nanoseconds: 300_000_000_000)

                await MainActor.run {
                    print("⏰ Timeout - no scan detected")
                    self.state = .disconnected
                    self.qrCode = nil
                }

            } catch {
                print("❌ ERROR: \(error)")
                print("❌ Error description: \(error.localizedDescription)")
                await MainActor.run {
                    self.errorMessage = "Error: \(error.localizedDescription)"
                    self.state = .disconnected
                    self.qrCode = nil
                }
            }
        }
    }

    func cancelPairing() {
        print("❌ Pairing cancelled")
        state = .disconnected
        qrCode = nil
        errorMessage = ""
    }

    func disconnect() {
        print("🔌 Disconnecting")
        state = .disconnected
    }

    private func getCurrentDeviceId() -> String {
        return UUID().uuidString
    }

    private func getCurrentDeviceName() -> String {
        let host = ProcessInfo.processInfo.hostName
        return Host.current().localizedName ?? host
    }
}

