package com.droidlink.core.network

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.net.Socket

/**
 * Simple TCP client for connecting to Mac server
 */
class TcpClient(
    private val host: String,
    private val port: Int
) {
    private var socket: Socket? = null
    private var writer: PrintWriter? = null
    private var reader: BufferedReader? = null

    /**
     * Connect to the server
     */
    suspend fun connect() = withContext(Dispatchers.IO) {
        socket = Socket(host, port)
        writer = PrintWriter(socket?.getOutputStream(), true)
        reader = BufferedReader(InputStreamReader(socket?.getInputStream()))
    }

    /**
     * Send a message to the server
     */
    suspend fun send(message: String) = withContext(Dispatchers.IO) {
        writer?.println(message)
    }

    /**
     * Receive a message from the server (blocking)
     */
    suspend fun receive(): String? = withContext(Dispatchers.IO) {
        reader?.readLine()
    }

    /**
     * Close the connection
     */
    suspend fun close() = withContext(Dispatchers.IO) {
        writer?.close()
        reader?.close()
        socket?.close()
        socket = null
        writer = null
        reader = null
    }

    /**
     * Check if connected
     */
    fun isConnected(): Boolean {
        return socket?.isConnected == true && socket?.isClosed == false
    }
}

import Foundation
import Network

/// Simple TCP server for receiving connections from Android
class TcpServer {
    private var listener: NWListener?
    private var connections: [NWConnection] = []

    /// Start the server on the specified port
    func start(port: UInt16, onConnection: ((NWConnection) -> Void)? = nil) throws {
        let config = NWListener.TcpOverlay(port: port)
        listener = try NWListener(using: config)

        listener?.newConnectionHandler = { [weak self] connection in
            print("📱 New connection from \(connection.endpoint)")
            self?.connections.append(connection)

            connection.stateUpdateHandler = { state in
                switch state {
                case .ready:
                    print("✅ Connection ready")
                    onConnection?(connection)
                case .failed(let error):
                    print("❌ Connection failed: \(error)")
                case .waiting(let error):
                    print("⏳ Connection waiting: \(error)")
                default:
                    break
                }
            }

            connection.start(queue: .main)
        }

        listener?.start(queue: .main)
        print("🚀 Server listening on port \(port)")
    }

    /// Stop the server
    func stop() {
        connections.forEach { $0.cancel() }
        connections.removeAll()
        listener?.cancel()
        listener = nil
    }
}

