@MainActor
class ContentViewModel: ObservableObject {
    @Published var state: ConnectionState = .disconnected
    @Published var qrCode: NSImage? = nil
    @Published var lastMessage: String? = nil

    private var tcpServer: TcpServer?
    private var qrCodeGenerator = QRCodeGenerator()

    init() {
        print("🎨 ContentViewModel initialized")
    }

    func startPairing() {
        print("🚀 Starting pairing process...")
        state = .pairing
        qrCode = nil

        Task {
            // Start TCP server
            do {
                print("🌐 Starting TCP server on port 9999...")
                tcpServer = TcpServer()
                try tcpServer?.start(port: 9999) { connection in
                    print("📱 Handling connection from Android")
                    connection.receiveMessage { content, context, isComplete, error in
                        if let data = content, !data.isEmpty {
                            let message = String(data: data, encoding: .utf8) ?? "Unable to decode"
                            print("📩 Received: \(message)")

                            DispatchQueue.main.async {
                                self.lastMessage = message
                            }

                            // Send response
                            let response = "Hello from Mac! Received: \(message)".data(using: .utf8)
                            connection.send(content: response!, completion: .contentProcessed { error in
                                if let error = error {
                                    print("❌ Send error: \(error)")
                                }
                            })
                        }
                    }
                }
                print("✅ TCP server started")
            } catch {
                print("❌ Failed to start server: \(error)")
            }

            // Generate QR code
            let deviceId = UUID().uuidString
            let deviceName = Host.current().localizedName ?? "Mac"
            let fingerprint = String((0..<64).map { _ in "0123456789abcdef".randomElement()! })

            let qr = qrCodeGenerator.generateQRCode(
                deviceId: deviceId,
                deviceName: deviceName,
                certificateFingerprint: fingerprint
            )

            self.qrCode = qr
            print("✅ QR code ready for scanning")
        }
    }

    func cancelPairing() {
        print("❌ Pairing cancelled")
        state = .disconnected
        qrCode = nil
        lastMessage = nil
        tcpServer?.stop()
    }

    func disconnect() {
        print("🔌 Disconnecting")
        state = .disconnected
        tcpServer?.stop()
    }
}

