extension NWConnection {
    /// Receive messages from the connection (simplified)
    func receiveMessage() -> String? {
        var receivedData = Data()
        let semaphore = DispatchSemaphore(value: 0)

        receive(minimumIncompleteLength: 1, maximumLength: 65536) { data, _, isComplete, error in
            if let data = data {
                receivedData.append(data)
            }
            if isComplete || error != nil {
                semaphore.signal()
            }
        }

        semaphore.wait()
        return String(data: receivedData, encoding: .utf8)
    }

    /// Send string message over the connection
    func sendMessage(_ message: String) -> Bool {
        guard let data = message.data(using: .utf8) else { return false }
        let semaphore = DispatchSemaphore(value: 0)

        send(content: data) { error in
            semaphore.signal()
        }

        return semaphore.wait(timeout: .now() + 5) == .success
    }
}

